using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S1.Recurrence.Algebraic;

internal sealed class ExponentialDifferentialFieldDocument : IScribeDocumentDefinition
{
    private const string Prefix = "D5/S1/Recurrence/Algebraic/ExponentialDifferentialField.";

    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "The normalized series -log(2-exp X) is transcendental over the rational function field generated by X and exp X.",
        H("The Exponential Differential Field"),
        Blocks(
            Paragraph(Text(
                "Work inside the fraction field L of rational formal power series. "
                + "The rational function field K=Q(t) embeds into L by t mapping to X. "
                + "The exponential is transcendental over K, so H=K(u) embeds by u mapping to exp X. "
                + "The derivation on K sends t to one, and that on H also sends u to u. "
                + "These derivations agree with the formal power series derivative after embedding into L. "
                + "All statements and constructions here are repository-derived.")),
            Remark("L", "The ambient field", "L is the fraction field of Q[[X]]."),
            Remark("K", "Rational functions in the variable", "K is the rational function field Q(t)."),
            Remark("H", "Rational functions in the variable and exponential", "H is the rational function field K(u)."),
            Remark("expImage", "The exponential image", "expImage is the image of exp X in L."),
            Remark("logImage", "The logarithmic image", "logImage is the image of the normalized formal series -log(2-exp X) in L."),
            Remark("F", "The normalized formal series", "F is the rational formal series -log(2-exp X), defined by the formal logarithm of the constant-one series 2-exp X."),
            Theorem("normalized_characterization", "The normalized primitive", "F has constant coefficient zero and derivative exp X times the inverse of 2-exp X. Any rational formal power series with this constant coefficient and derivative equals F. The logarithmic derivative formula follows by substitution into the formal identity (1+X)log'(1+X)=1, and equality of the derivative and constant coefficient gives uniqueness."),
            Theorem("kX_image", "The first variable", "The image of t from K in L is the image of the formal power series variable X."),
            Theorem("hX_image", "The exponential variable", "The image of u from H in L is expImage."),
            Theorem("logImage_derivative", "The logarithmic derivative", "The derivative of logImage is the image of u/(2-u) from H in L. The denominator has nonzero constant coefficient, so the identity follows from the normalized formal derivative formula."),
            Theorem("rational_image", "The derivative as a rational function", "The image of u/(2-u) equals the embedded formal derivative of -log(2-exp X)."),
            Theorem("logImage_transcendental", "Transcendence over the exponential field", "The element logImage is transcendental over H. If it were algebraic, descent of algebraic primitives would give a primitive of u/(2-u) in H. The pole at u=2 rules out such a rational primitive."))));

    private static DocumentBlock Remark(string name, string title, string text) => Describe.Remark(
        DescribeId.Create("exponential-differential-field-" + name.ToLowerInvariant().Replace('_', '-')),
        DeclarationHandle.Create(Prefix + name), H(title), AssessedProvenance.FromRepo(),
        Blocks(Paragraph(Text(text))));

    private static DocumentBlock Theorem(string name, string title, string text) => Describe.Lean(
        DescribeId.Create("exponential-differential-field-" + name.ToLowerInvariant().Replace('_', '-')),
        DeclarationHandle.Create(Prefix + name), H(title), StatementSource.WithoutFormula(),
        AssessedProvenance.FromRepo(), Blocks(Paragraph(Text(text))), DescribeRole.Theorem);
}
